# The edit failure count was inflated by the broad regex. Let me do a proper count
# using python3 to look at actual tool error results
python3 << 'EOF'
import json, os, glob, re
from collections import defaultdict

sessions_dir = ".state/sessions/history"
min_ts = 1774160000000

edit_fail_details = defaultdict(lambda: {'actual_fails': 0, 'total_edits': 0, 'sessions_with_fails': []})

for d in sorted(glob.glob(f"{sessions_dir}/s_*")):
    sid = os.path.basename(d)
    parts = sid.split('_')
    try:
        ts = int(parts[1])
        if ts < min_ts:
            continue
    except:
        continue

    meta_path = f"{d}/meta.json"
    session_path = f"{d}/session.jsonl"
    if not os.path.exists(meta_path) or not os.path.exists(session_path):
        continue

    try:
        meta = json.load(open(meta_path))
        agent = meta.get('agent', '?')
    except:
        continue

    try:
        lines = open(session_path).readlines()
    except:
        continue

    edit_count = 0
    edit_fail_count = 0

    for i, line in enumerate(lines):
        try:
            obj = json.loads(line)
        except:
            continue

        # Count tool_use of edit
        if isinstance(obj, dict):
            content = obj.get('content', [])
            if isinstance(content, list):
                for block in content:
                    if isinstance(block, dict):
                        if block.get('type') == 'tool_use' and block.get('name') == 'edit':
                            edit_count += 1
                        # Check tool results for edit errors
                        if block.get('type') == 'tool_result' and block.get('is_error') == True:
                            text = str(block.get('content', ''))
                            if 'edit' in text.lower() or 'oldText' in text or 'not found' in text:
                                edit_fail_count += 1

    edit_fail_details[agent]['total_edits'] += edit_count
    if edit_fail_count > 0:
        edit_fail_details[agent]['actual_fails'] += edit_fail_count
        edit_fail_details[agent]['sessions_with_fails'].append((sid, edit_fail_count, edit_count))

print("ACTUAL EDIT FAILURES (from tool_result is_error=true):")
for agent, data in sorted(edit_fail_details.items(), key=lambda x: -x[1]['actual_fails']):
    if data['actual_fails'] > 0:
        print(f"\n  {agent}: {data['actual_fails']} edit failures / {data['total_edits']} edits")
        for sid, fails, edits in data['sessions_with_fails']:
            print(f"    {sid}: {fails} failures, {edits} edits")

# Also count: what % of edits had a read() of the same path beforehand?
print("\nNOTE: is_error field not always present in tool_result. Checking text-based markers...")
EOF

