# Different format - uses 'toolCall' not 'tool_use'. Let me extract bash-as-cat from this format
python3 << 'PYEOF'
import json, sys

session_file = ".state/sessions/s_1774022326806_81/session.jsonl"
bash_total = 0
bash_as_cat = 0
read_total = 0

with open(session_file) as f:
    for line in f:
        msg = json.loads(line.strip())
        if msg.get('role') != 'assistant':
            continue
        content = msg.get('content', [])
        if not isinstance(content, list):
            continue
        for c in content:
            if c.get('type') == 'toolCall':
                fn = c.get('function', {})
                name = fn.get('name', '')
                args_str = fn.get('arguments', '{}')
                try:
                    args = json.loads(args_str) if isinstance(args_str, str) else args_str
                except:
                    args = {}

                if name == 'bash':
                    bash_total += 1
                    cmd = args.get('command', '')
                    # Simple file reading commands
                    import re
                    if re.match(r'^\s*(cat|head|tail|less)\s+\S+\s*$', cmd):
                        bash_as_cat += 1
                        print(f"  bash-as-cat: {cmd.strip()[:80]}")
                elif name == 'read':
                    read_total += 1

print(f"\nTotals: bash={bash_total}, read={read_total}, bash-as-cat={bash_as_cat}")
print(f"bash-as-cat rate: {bash_as_cat}/{bash_total} = {100*bash_as_cat/max(bash_total,1):.1f}%")
PYEOF

