import json, re

session_file = ".state/sessions/s_1774022326806_81/session.jsonl"
bash_total = 0
bash_as_cat = 0
read_total = 0
edit_total = 0
edit_fail = 0
write_total = 0
cat_examples = []

with open(session_file) as f:
    for line in f:
        msg = json.loads(line.strip())
        content = msg.get('content', [])
        if not isinstance(content, list):
            continue

        for c in content:
            if c.get('type') == 'toolCall':
                name = c.get('name', '')
                args = c.get('arguments', {})
                if not isinstance(args, dict):
                    try:
                        args = json.loads(args)
                    except:
                        args = {}

                if name == 'bash':
                    bash_total += 1
                    cmd = args.get('command', '')
                    if re.match(r'^\s*(cat|head -\d+|tail -\d+)\s+\S+\s*$', cmd):
                        bash_as_cat += 1
                        cat_examples.append(cmd.strip()[:100])
                elif name == 'read':
                    read_total += 1
                elif name == 'edit':
                    edit_total += 1
                elif name == 'write':
                    write_total += 1

            # Check for edit failures in tool results
            if c.get('type') == 'toolResult' or c.get('type') == 'tool_result':
                text = c.get('text', '') or str(c.get('content', ''))
                if 'oldText not found' in text or 'No match found' in text:
                    edit_fail += 1

meta = json.load(open(".state/sessions/s_1774022326806_81/meta.json"))
agent = meta.get('agent', '?')

print(f"Session s_81 ({agent}):")
print(f"  bash: {bash_total}, read: {read_total}, edit: {edit_total}, write: {write_total}")
print(f"  bash-as-cat: {bash_as_cat} ({100*bash_as_cat/max(bash_total,1):.0f}% of bash)")
print(f"  edit failures: {edit_fail}")
if cat_examples:
    print(f"  Cat examples:")
    for ex in cat_examples[:5]:
        print(f"    {ex}")
PYEOF
